const screen_width=40
const screen_height=30
const screen_resol=9
const image_size=4800
const frame_nr=544

create_sp 0xf000

mov r8, 0
screen r8, 3
mov r8, 1
add r1, zr, screenBuf
screen r8, r1
mov r8, 2
screen r8, screen_resol ;;;;;;;; factor

main:
add r1, zr, screenBuf 
sub sp, sp, 0x20
str [sp,0x00], r1 ;buf_ptr
mov r1, screen_width
str [sp,0x04], r1 ;width
mov r1, screen_height
str [sp,0x08], r1 ;height

add r1, zr, screenBuf 
add r2, zr, image_size
add r2, r2, 1
add r1, r2, r1 ; image_ptr
str [sp,0x0c], r1

mov r1, frame_nr ; frames
str [sp,0x10], r1
str [sp,0x14], zr

main_loop:
ld r1, [sp,0x10]
ld r2, [sp,0x14]
cmp r1, r2
jbe main_loop_end

add r8, sp, 0x00
mov r1, 0x00
mov r2, 0x00
ld r3, [sp,0x04]
ld r4, [sp,0x08]
ld r5, [sp,0x0c]

add r6, zr, image_size
add r6, r6, r5
str [sp,0x0c], r6

call screen_fill

ld r1, [sp,0x14]
add r1, r1, 1
str [sp,0x14], r1

jmp main_loop
main_loop_end:
add sp, sp, 0x20
jmp main

mul:
    mov r13, 0
    mov r8, 0
    mul_loop:
        cmp r13, r4
        jge mul_end
            add r8, r8, r3
        add r13, r13, 1
        jmp mul_loop

	

;screen_fill( r8:screenInfo_ptr, r1:x1, r2:y1, r3:x2, r4:y2, r5:image_ptr )
screen_fill:
    ld r6, [r8,0x04]; r8=buf_ptr r6=width r7=height
    ld r7, [r8,0x08]
    ld r8, [r8,0x00]

    sub sp, sp, 0x30
    str [sp,0x00], r8 ;buf_ptr
    str [sp,0x04], r6 ;width
    str [sp,0x08], r7 ;height
    str [sp,0x0c], r1 ;x1
    str [sp,0x10], r2 ;y1
    str [sp,0x14], r3 ;x2
    str [sp,0x18], r4 ;y2
    str [sp,0x1c], r5 ;image_ptr

    mov r1, r2
    str [sp,0x24], r2 ;i
    screen_fill_loop1:
        ld r2, [sp,0x18]
        cmp r1, r2
        je screen_fill_loop1_end

        ld r1, [sp,0x0c]
        str [sp,0x20], r1 ;j
        screen_fill_loop2:
            ld r2, [sp,0x14]
            cmp r1, r2
            je screen_fill_loop2_end
            
            ld r3, [sp,0x24] ;i*width+j <<2
            ld r4, [sp,0x04]
            jmp mul
            mul_end:
            ld r7, [sp,0x20]
            add r8, r7, r8
            lsl r8, r8, 0x02
            
            ld r1, [sp,0x1c] ; image_ptr
            add r1, r1, r8
            ld r2, [r1,0x00]

            ld r1, [sp,0x00]
            add r8, r1, r8  ; screenBuf[ r8 ]

            str [r8,0x00], r2

            mov r1, r7
            add r1, r1, 1
            str [sp,0x20], r1
            jmp screen_fill_loop2
        screen_fill_loop2_end:
        ld r1, [sp,0x24]
        add r1, r1, 1
        str [sp,0x24], r1
        jmp screen_fill_loop1 
    screen_fill_loop1_end:
    add sp, sp, 0x30
    ret

